#!/usr/bin/env tsx
// Reads all .m files from stdlib/ and generates src/numbl-core/stdlib-bundle.ts
//
// - stdlib/*.m        → stdlibFiles (flat, no search path needed)
// - stdlib/shims/**   → shimFiles   (preserves relative paths, needs search path)
//
// The generated file is committed. CI runs `--check` to catch drift, and the
// test entry points (vitest globalSetup, test:scripts, jit-parity) regenerate
// it first so they never run against a stale copy.
//
// Usage:
//   npx tsx scripts/bundle-stdlib.ts            # regenerate (no-op if unchanged)
//   npx tsx scripts/bundle-stdlib.ts --check    # exit 1 if out of date

import { readdirSync, readFileSync, statSync, writeFileSync } from "fs";
import { join, relative, resolve } from "path";
import { pathToFileURL } from "url";

const ROOT = resolve(import.meta.dirname, "..");
const STDLIB_DIR = join(ROOT, "src/stdlib");
const SHIMS_DIR = join(STDLIB_DIR, "shims");
const OUT_FILE = join(ROOT, "src/numbl-core/stdlib-bundle.ts");

// Recursively collect shim .m files (following @, +, and private dirs like the CLI scanner)
interface FileEntry {
  name: string;
  source: string;
}

function scanMFiles(dir: string, baseDir: string): FileEntry[] {
  const results: FileEntry[] = [];
  let entries: string[];
  try {
    entries = readdirSync(dir);
  } catch {
    return results;
  }
  entries.sort();
  for (const entry of entries) {
    const fullPath = join(dir, entry);
    const stat = statSync(fullPath);
    if (stat.isDirectory()) {
      if (
        entry.startsWith("@") ||
        entry.startsWith("+") ||
        entry === "private"
      ) {
        results.push(...scanMFiles(fullPath, baseDir));
      }
    } else if (stat.isFile() && entry.endsWith(".m")) {
      const relPath = relative(baseDir, fullPath);
      results.push({
        name: relPath,
        source: readFileSync(fullPath, "utf-8"),
      });
    }
  }
  return results;
}

// Generate output
function emitArray(varName: string, entries: FileEntry[]): string[] {
  const lines: string[] = [];
  lines.push(`export const ${varName}: WorkspaceFile[] = [`);
  for (const { name, source } of entries) {
    lines.push("  {");
    lines.push(`    name: ${JSON.stringify(name)},`);
    lines.push(`    source: ${JSON.stringify(source)},`);
    lines.push("  },");
  }
  lines.push("];");
  return lines;
}

function generate() {
  const stdlibEntries = readdirSync(STDLIB_DIR)
    .filter(f => f.endsWith(".m"))
    .sort()
    .map(name => ({
      name,
      source: readFileSync(join(STDLIB_DIR, name), "utf-8"),
    }));
  const shimEntries = scanMFiles(SHIMS_DIR, SHIMS_DIR);
  const content = [
    "// Auto-generated by scripts/bundle-stdlib.ts — do not edit manually.",
    'import type { WorkspaceFile } from "./workspace/types.js";',
    "",
    ...emitArray("stdlibFiles", stdlibEntries),
    "",
    ...emitArray("shimFiles", shimEntries),
    "",
  ].join("\n");
  return { content, stdlibEntries, shimEntries };
}

function readExisting(): string | null {
  try {
    return readFileSync(OUT_FILE, "utf-8");
  } catch {
    return null;
  }
}

/** Regenerate the bundle if it differs from the sources. Returns true if written. */
export function bundleStdlib(opts: { quiet?: boolean } = {}): boolean {
  const { content, stdlibEntries, shimEntries } = generate();
  if (readExisting() === content) {
    if (!opts.quiet) console.log("stdlib-bundle.ts is up to date.");
    return false;
  }
  writeFileSync(OUT_FILE, content);
  console.log(
    `stdlib-bundle.ts generated: ${stdlibEntries.length} stdlib, ${shimEntries.length} shim file(s)`
  );
  return true;
}

// Vitest globalSetup entry (see vite.config.ts).
export function setup(): void {
  bundleStdlib({ quiet: true });
}

const isMain =
  process.argv[1] !== undefined &&
  import.meta.url === pathToFileURL(resolve(process.argv[1])).href;

if (isMain) {
  if (process.argv.includes("--check")) {
    if (readExisting() !== generate().content) {
      console.error(
        "src/numbl-core/stdlib-bundle.ts is out of date with src/stdlib/. " +
          "Run `npm run bundle:stdlib` and commit the result."
      );
      process.exit(1);
    }
    console.log("stdlib-bundle.ts is up to date.");
  } else {
    bundleStdlib();
  }
}
